package me.raddatz.veyq.core.crypto

import com.fasterxml.jackson.databind.JsonNode
import com.fasterxml.jackson.databind.ObjectMapper
import org.junit.jupiter.api.Assertions.assertArrayEquals
import org.junit.jupiter.api.Assertions.assertFalse
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test
import java.io.File
import java.util.Base64
import java.util.HexFormat

/**
 * The backend's `invite-key` and `invite-accept` bytes are the contract's (`invite_key` and `join_record` in the crypto
 * vectors, generated by an independent Python implementation and asserted by `packages/crypto` too). The server rebuilds
 * both statements to check the owner's signature at an invite's mint and the invite key's proof at its accept, so a
 * drift between the two stacks is every member invite refused — this reddens first.
 */
class InviteAcceptProofTest {

    private val vectors: JsonNode = ObjectMapper().readTree(File("../../contracts/crypto/vectors/v1.json"))
    private val k = vectors["invite_key"]
    private val j = vectors["join_record"]
    private val ctx = k["context"]
    private val tenantId = ctx["tenantId"].asText()
    private val inviteId = ctx["inviteId"].asText()
    private val expiresAt = ctx["expiresAt"].asLong()
    private val inviteBundle = b64(k["bundle"])
    private val ownerBundle = b64(k["owner"]["bundle"])
    private val joinerBundle = b64(j["joiner_bundle"])
    private val userId = j["context"]["userId"].asText()

    @Test
    fun theInviteKeyStatementIsTheVectorsAndTheOwnersSignatureVerifies() {
        assertArrayEquals(hex(k["statement"]), InviteAcceptProof.inviteKeyStatement(tenantId, inviteId, inviteBundle, expiresAt))
        assertTrue(InviteAcceptProof.inviteKeyVerifies(ownerBundle, tenantId, inviteId, inviteBundle, expiresAt, b64(k["signature"])))
    }

    @Test
    fun theOwnersSignatureAnswersForNoOtherInviteExpiryOrKey() {
        val sig = b64(k["signature"])
        val other = "c0ffee00-0000-4000-8000-0000000000e0"
        assertFalse(InviteAcceptProof.inviteKeyVerifies(ownerBundle, other, inviteId, inviteBundle, expiresAt, sig))
        assertFalse(InviteAcceptProof.inviteKeyVerifies(ownerBundle, tenantId, other, inviteBundle, expiresAt, sig))
        assertFalse(InviteAcceptProof.inviteKeyVerifies(ownerBundle, tenantId, inviteId, inviteBundle, expiresAt + 1, sig))
        assertFalse(InviteAcceptProof.inviteKeyVerifies(ownerBundle, tenantId, inviteId, joinerBundle, expiresAt, sig))
        assertFalse(InviteAcceptProof.inviteKeyVerifies(joinerBundle, tenantId, inviteId, inviteBundle, expiresAt, sig))
        assertFalse(InviteAcceptProof.inviteKeyVerifies(null, tenantId, inviteId, inviteBundle, expiresAt, sig))
        assertFalse(InviteAcceptProof.inviteKeyVerifies("not base64!", tenantId, inviteId, inviteBundle, expiresAt, sig))
    }

    @Test
    fun theAcceptStatementIsTheVectorsAndTheInviteKeysProofVerifies() {
        assertArrayEquals(hex(j["accept_statement"]), InviteAcceptProof.statement(inviteId, userId, joinerBundle))
        assertTrue(InviteAcceptProof.verify(inviteBundle, inviteId, userId, joinerBundle, b64(j["accept_signature"])))
        // Control: the same proof answers for no other account, identity or key.
        val sig = b64(j["accept_signature"])
        assertFalse(InviteAcceptProof.verify(inviteBundle, inviteId, "b0b00000-0000-4000-8000-0000000000e0", joinerBundle, sig))
        assertFalse(InviteAcceptProof.verify(inviteBundle, inviteId, userId, ownerBundle, sig))
        assertFalse(InviteAcceptProof.verify(ownerBundle, inviteId, userId, joinerBundle, sig))
    }

    @Test
    fun aRecipientDigestMatchesOnlyItsBundle() {
        val digest = Base64.getEncoder().encodeToString(hex(k["bundle_digest"]))
        assertTrue(InviteAcceptProof.digestMatches(inviteBundle, digest))
        assertFalse(InviteAcceptProof.digestMatches(ownerBundle, digest))
    }

    private fun hex(n: JsonNode): ByteArray = HexFormat.of().parseHex(n.asText())
    private fun b64(n: JsonNode): String = Base64.getEncoder().encodeToString(hex(n))
}
